def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Record aggregate behavior of opponent.
    opp_c = 0
    opp_d = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1
        else:
            opp_d += 1

    # Current final run lengths for both players.
    last_opp = history[-1][1]
    last_me = history[-1][0]

    opp_run = 0
    for _, o in reversed(history):
        if o == last_opp:
            opp_run += 1
        else:
            break

    my_run = 0
    for m, _ in reversed(history):
        if m == last_me:
            my_run += 1
        else:
            break

    # Recent window stats.
    w = 10 if n >= 10 else n
    recent = history[-w:]
    rec_c = 0
    rec_d = 0
    for _, o in recent:
        if o == 'C':
            rec_c += 1
        else:
            rec_d += 1

    my_recent_c = 0
    my_recent_d = 0
    for m, _ in recent:
        if m == 'C':
            my_recent_c += 1
        else:
            my_recent_d += 1

    remaining = 100 - n

    # Always try to keep mutual cooperation alive unless opponent is clearly hostile.
    if opp_d == 0:
        # Opponent has never defected. Cooperate, except occasional late exploitation.
        if remaining <= 2:
            return 'D'
        if remaining <= 5 and rng.random() < 0.35:
            return 'D'
        if n >= 4 and my_run >= 3 and rng.random() < 0.04:
            return 'D'
        return 'C'

    # If opponent has defected only rarely, be very forgiving.
    if opp_d <= 2:
        if last_opp == 'D':
            # Forgive isolated defections, especially early or after ours.
            if last_me == 'D':
                return 'C'
            if opp_run == 1:
                return 'C'
            if n <= 5:
                return 'C'
            if rng.random() < 0.75:
                return 'C'
            return 'D'
        # Opponent cooperated.
        if remaining <= 2:
            return 'D'
        if remaining <= 6 and rng.random() < 0.25:
            return 'D'
        if my_run >= 4 and rng.random() < 0.03:
            return 'D'
        return 'C'

    # Opponent is mixed. Use a forgiving but retaliatory scheme based on recent rate.
    rec_rate = rec_c / w

    if rec_rate >= 0.8:
        # Mostly cooperative recently: cooperate, with modest probing.
        if remaining <= 1:
            return 'D'
        if remaining <= 4 and rng.random() < 0.4:
            return 'D'
        if my_run >= 5 and rng.random() < 0.05:
            return 'D'
        return 'C'

    if rec_rate <= 0.25:
        # Mostly hostile recently: defect, but occasionally test for cooperation.
        if remaining <= 3:
            return 'D'
        if opp_run >= 3:
            return 'D'
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Middle range.
    if last_opp == 'D':
        if opp_run >= 3:
            return 'D'
        if last_me == 'D' and opp_run == 1:
            # Opponent defected after we did: likely retaliation, so return to C.
            return 'C'
        if opp_run == 1 and rng.random() < 0.45:
            return 'C'
        return 'D'

    # Last opponent action was C.
    if last_me == 'D':
        # We defected, they cooperated: return cooperation to rebuild.
        return 'C'
    if remaining <= 1:
        return 'D'
    if remaining <= 3 and rng.random() < 0.35:
        return 'D'
    if my_run >= 6 and rng.random() < 0.06:
        return 'D'
    return 'C'
